public class InnerDataAccessorAttributeFilterFactory(Action<Humidifier.QBusiness.DataAccessorTypes.AttributeFilter> factoryAction = null) : SubResourceFactory<Humidifier.QBusiness.DataAccessorTypes.AttributeFilter>
{

    internal InnerDataAccessorDocumentAttributeFactory ContainsAnyFactory { get; set; }

    internal InnerDataAccessorDocumentAttributeFactory LessThanFactory { get; set; }

    internal InnerDataAccessorDocumentAttributeFactory GreaterThanFactory { get; set; }

    internal InnerDataAccessorAttributeFilterFactory NotFilterFactory { get; set; }

    internal InnerDataAccessorDocumentAttributeFactory LessThanOrEqualsFactory { get; set; }

    internal InnerDataAccessorDocumentAttributeFactory EqualsToFactory { get; set; }

    internal InnerDataAccessorDocumentAttributeFactory GreaterThanOrEqualsFactory { get; set; }

    internal InnerDataAccessorDocumentAttributeFactory ContainsAllFactory { get; set; }

    protected override Humidifier.QBusiness.DataAccessorTypes.AttributeFilter Create()
    {
        var attributeFilterResult = CreateAttributeFilter();
        factoryAction?.Invoke(attributeFilterResult);

        return attributeFilterResult;
    }

    private Humidifier.QBusiness.DataAccessorTypes.AttributeFilter CreateAttributeFilter()
    {
        var attributeFilterResult = new Humidifier.QBusiness.DataAccessorTypes.AttributeFilter();

        return attributeFilterResult;
    }
    public override void CreateChildren(Humidifier.QBusiness.DataAccessorTypes.AttributeFilter result)
    {
        base.CreateChildren(result);

        result.ContainsAny ??= ContainsAnyFactory?.Build();
        result.LessThan ??= LessThanFactory?.Build();
        result.GreaterThan ??= GreaterThanFactory?.Build();
        result.NotFilter ??= NotFilterFactory?.Build();
        result.LessThanOrEquals ??= LessThanOrEqualsFactory?.Build();
        result.EqualsTo ??= EqualsToFactory?.Build();
        result.GreaterThanOrEquals ??= GreaterThanOrEqualsFactory?.Build();
        result.ContainsAll ??= ContainsAllFactory?.Build();
    }

} // End Of Class

